import math

def solve(grant_date, exercise_date, sale_date):
    def parse_date(date_str):
        parts = date_str.split('-')
        return int(parts[0]), int(parts[1]), int(parts[2])

    def is_leap(year):
        return (year % 4 == 0 and year % 100 != 0) or (year % 400 == 0)

    def days_in_month(year, month):
        if month == 2:
            return 29 if is_leap(year) else 28
        elif month in [4, 6, 9, 11]:
            return 30
        else:
            return 31

    def total_days(year, month, day):
        days = 0
        for y in range(1, year):
            days += 366 if is_leap(y) else 365
        for m in range(1, month):
            days += days_in_month(year, m)
        days += day
        return days

    g_year, g_month, g_day = parse_date(grant_date)
    e_year, e_month, e_day = parse_date(exercise_date)
    s_year, s_month, s_day = parse_date(sale_date)

    total_days_grant = total_days(g_year, g_month, g_day)
    total_days_exercise = total_days(e_year, e_month, e_day)
    total_days_sale = total_days(s_year, s_month, s_day)

    # Calculate date differences
    days_exercise_to_sale = total_days_sale - total_days_exercise
    days_grant_to_sale = total_days_sale - total_days_grant

    # Check conditions
    condition1 = days_exercise_to_sale > 365
    condition2 = days_grant_to_sale > 730

    return condition1 and condition2
